<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;

use CetechDeliveryEngine\Infrastructure\Persistence\{CustomerPolicyReceiptStore as Store,CustomerPolicyReceiptUnit,CustomerPolicyReceiptStorageException};
use CetechDeliveryEngine\Infrastructure\WordPress\OperationConnection;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyReceiptTestTransport as T;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyDomainFixture as F;
use PHPUnit\Framework\TestCase;

final class CustomerPolicyReceiptStoreTest extends TestCase {
	private function fixture(?callable$configure=null):array{$pdo=T::database();$transports=[];$store=new Store(1,'wp_',static function()use($pdo,&$transports,$configure):T{$t=new T($pdo);$transports[]=$t;if(null!==$configure){$configure($t,count($transports));}return$t;});return[$store,$pdo,&$transports];}
	private function subject(string$char='a'):string{return str_repeat($char,64);}
	private function refuse(callable$work,?string$outcome=null):void{$caught=null;try{$work();}catch(CustomerPolicyReceiptStorageException$e){$caught=$e;}self::assertInstanceOf(CustomerPolicyReceiptStorageException::class,$caught);if(null!==$outcome){self::assertSame($outcome,$caught->outcome);}}
	public function test_deferred_wordpress_construction_is_inert_without_any_native_route():void{$r=$this->route_probe('construct-only');self::assertSame(0,$r['constructor_site_reads']);self::assertNull($r['first']);self::assertNull($r['second']);self::assertTrue($r['refused']);}
	public function test_deferred_native_route_is_bound_once_and_never_retargets():void{foreach(['replace-object','change-site','change-prefix','change-host']as$mode){$r=$this->route_probe($mode);self::assertSame(0,$r['constructor_site_reads']);self::assertSame(['site_id'=>1,'prefix'=>'wp_'],$r['first']);self::assertNull($r['second']);self::assertTrue($r['refused']);}}
	public function test_deferred_native_binding_remains_exact_on_unchanged_host():void{$r=$this->route_probe('same');self::assertSame(0,$r['constructor_site_reads']);self::assertSame($r['first'],$r['second']);self::assertFalse($r['refused']);}
	private function route_probe(string$mode):array{$path=dirname(__DIR__,2).'/Support/CustomerPolicy/customer-policy-store-route-probe.php';$lines=[];$exit=0;exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg($path).' '.escapeshellarg($mode),$lines,$exit);self::assertSame(0,$exit);return json_decode(implode('\n',$lines),true,16,JSON_THROW_ON_ERROR);}
	public function test_read_only_cart_probe_creates_no_option_or_business_history():void{[$s,$pdo]=$this->fixture();self::assertNull($s->transaction($this->subject(),static fn($u)=>$u->cart()));self::assertSame(0,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());}
	public function test_cart_and_original_are_committed_together_with_exact_unicode_and_literal_bytes():void{[$s,$pdo]=$this->fixture();$bytes='{"text":"Unicode Ω—漢字; literal <b> & \\ \' quotes"}';$out=$s->transaction($this->subject(),static function($u)use($bytes){$a=$u->put_cart(null,$bytes);$b=$u->put_original(F::uuid(700),null,$bytes);return[$a,$b];});self::assertCount(2,$out);self::assertSame($bytes,$out[0]['bytes']);self::assertSame($bytes,$out[1]['bytes']);self::assertSame('off',$out[0]['autoload']);self::assertSame(2,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());}
	public function test_failed_second_write_rolls_back_the_entire_handoff():void{[$s,$pdo]=$this->fixture();$this->refuse(fn()=>$s->transaction($this->subject(),static function($u){$u->put_cart(null,'{"one":1}');$u->put_original(F::uuid(700),['row_id'=>99],'{}');}));self::assertSame(0,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());}
	public function test_proven_unsent_commit_rolls_back_then_separate_original_retry_can_commit():void{[$s,$pdo]=$this->fixture(static function(T$t,int$n):void{if(1===$n){$t->commit_fault='unsent';}});$work=static function($u){$u->put_cart(null,'{"a":1}');$u->put_original(F::uuid(700),null,'{"a":2}');return true;};$this->refuse(fn()=>$s->transaction($this->subject(),$work),'not_sent');self::assertSame(0,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());self::assertTrue($s->transaction($this->subject(),$work));self::assertSame(2,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());}
	public function test_lost_commit_ack_is_unknown_but_fresh_owner_observes_both_original_rows():void{[$s,$pdo]=$this->fixture(static function(T$t,int$n):void{if(1===$n){$t->commit_fault='lost_ack';}});$this->refuse(fn()=>$s->transaction($this->subject(),static function($u){$u->put_cart(null,'{"a":1}');$u->put_original(F::uuid(700),null,'{"a":2}');}),'outcome_unknown');self::assertSame(2,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());$rows=$s->transaction($this->subject(),static fn($u)=>[$u->cart(),$u->original(F::uuid(700))]);self::assertSame('{"a":1}',$rows[0]['bytes']);self::assertSame('{"a":2}',$rows[1]['bytes']);}
	public function test_existing_autoload_and_physical_id_are_preserved_by_exact_cas():void{[$s,$pdo]=$this->fixture();$name=Store::cart_name(1,$this->subject());$q=$pdo->prepare('INSERT INTO wp_options(option_name,option_value,autoload)VALUES(?,?,?)');$q->execute([$name,'{"a":1}','yes']);$row=$s->transaction($this->subject(),static function($u){$old=$u->cart();return[$old,$u->put_cart($old,'{"a":2}')];});self::assertSame($row[0]['row_id'],$row[1]['row_id']);self::assertSame('yes',$row[1]['autoload']);}
	public function test_identical_delete_reinsert_cannot_reuse_an_old_cas_handle():void{[$s,$pdo]=$this->fixture();$old=$s->transaction($this->subject(),static fn($u)=>$u->put_cart(null,'{"a":1}'));$pdo->exec('DELETE FROM wp_options');$q=$pdo->prepare('INSERT INTO wp_options(option_name,option_value,autoload)VALUES(?,?,?)');$q->execute([$old['option_name'],$old['bytes'],$old['autoload']]);$this->refuse(fn()=>$s->transaction($this->subject(),static fn($u)=>$u->put_cart($old,'{"a":2}')));self::assertSame('{"a":1}',$pdo->query('SELECT option_value FROM wp_options')->fetchColumn());}
	public function test_case_folded_option_name_is_not_the_exact_authority():void{[$s,$pdo]=$this->fixture();$q=$pdo->prepare('INSERT INTO wp_options(option_name,option_value,autoload)VALUES(?,?,?)');$q->execute([strtoupper(Store::cart_name(1,$this->subject())),'{}','off']);$this->refuse(fn()=>$s->transaction($this->subject(),static fn($u)=>$u->cart()));}
	public function test_prefix_unique_or_missing_unique_or_nontransactional_options_refuse_before_callback():void{foreach(['prefix_unique','no_unique','nontransactional','extra_column']as$fault){$calls=0;[$s]=$this->fixture(static function(T$t)use($fault):void{$t->schema_fault=$fault;});$this->refuse(fn()=>$s->transaction($this->subject(),static function()use(&$calls):void{++$calls;}));self::assertSame(0,$calls);}}
	public function test_subject_lock_is_nonwaiting_and_foreign_lock_is_not_released():void{[$s]=$this->fixture(static function(T$t):void{$t->before=static function(string$sql,T$t):void{if(preg_match("/GET_LOCK\('([^']+)'/",$sql,$m)){T::$locks[$t->database.':'.$m[1]]=999;}};});$this->refuse(fn()=>$s->transaction($this->subject(),static fn()=>true),'unavailable');self::assertContains(999,T::$locks);T::$locks=[];}
	public function test_max_packet_pre_dispatch_bound_refuses_without_a_cart_row():void{[$s,$pdo]=$this->fixture(static function(T$t):void{$t->max_packet=4096;});$this->refuse(fn()=>$s->transaction($this->subject(),static fn($u)=>$u->put_cart(null,str_repeat('x',4096))),'not_sent');self::assertSame(0,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());}
	public function test_cart_exact_bound_and_plus_one_leave_the_original_bytes_unchanged():void{[$s,$pdo]=$this->fixture();$bytes=str_repeat('a',Store::CART_MAX_BYTES);$row=$s->transaction($this->subject(),static fn($u)=>$u->put_cart(null,$bytes));self::assertSame(Store::CART_MAX_BYTES,strlen($row['bytes']));$this->refuse(fn()=>$s->transaction($this->subject(),static fn($u)=>$u->put_cart($row,$bytes.'a')),'unavailable');self::assertSame($bytes,$pdo->query('SELECT option_value FROM wp_options')->fetchColumn());}
	public function test_physical_witness_rejects_same_bytes_original_reinsert():void{[$s,$pdo]=$this->fixture();$rows=$s->transaction($this->subject(),static fn($u)=>[$u->put_cart(null,'{"a":1}'),$u->put_original(F::uuid(700),null,'{"b":2}')]);$w=['site_id'=>1,'prefix'=>'wp_','subject'=>$this->subject(),'attempt_id'=>F::uuid(700),'cart'=>$rows[0],'original'=>$rows[1],'order_index'=>null];$session=new OperationConnection(1,'wp_',new T($pdo));self::assertTrue($session->begin());self::assertTrue(Store::verify_witness($session,$w));self::assertTrue($session->rollback());self::assertTrue($session->retire());$pdo->exec('DELETE FROM wp_options WHERE option_id='.$rows[1]['row_id']);$q=$pdo->prepare('INSERT INTO wp_options(option_name,option_value,autoload)VALUES(?,?,?)');$q->execute([$rows[1]['option_name'],$rows[1]['bytes'],'off']);$session=new OperationConnection(1,'wp_',new T($pdo));self::assertTrue($session->begin());self::assertFalse(Store::verify_witness($session,$w));self::assertTrue($session->rollback());self::assertTrue($session->retire());}
	public function test_reentrant_owner_is_refused_and_does_not_emit_partial_success():void{[$s,$pdo]=$this->fixture();$this->refuse(fn()=>$s->transaction($this->subject(),fn()=>$s->transaction($this->subject(),static fn()=>true)));self::assertSame(0,(int)$pdo->query('SELECT COUNT(*) FROM wp_options')->fetchColumn());}
	public function test_invalid_subject_does_not_open_transport():void{$opened=0;$s=new Store(1,'wp_',static function()use(&$opened){++$opened;throw new \RuntimeException();});foreach(['',str_repeat('a',63),str_repeat('A',64)]as$subject){$this->refuse(fn()=>$s->transaction($subject,static fn()=>true),'unavailable');}self::assertSame(0,$opened);}
}
